def generate(rng):
    # A tiled grid: 2x2 cells separated by full-width/height lines of 6.
    nr = rng.randint(3,6)   # cell rows
    nc = rng.randint(3,6)   # cell columns
    h = 2*nr + (nr-1)
    w = 2*nc + (nc-1)
    g = [[0]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
